    background: #f5f7fa;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
  }
  .card {
    background: #fff;
    border-radius: 16px;
    box-shadow: 0 4px 24px rgba(0,0,0,0.08);
    padding: 40px 36px;
    max-width: 480px;
    width: 100%;
    text-align: center;
  }
  .badge {
    display: inline-block;
    background: #e8f4fd;
    color: #1677ff;
    font-size: 13px;
    font-weight: 600;
    padding: 4px 14px;
    border-radius: 20px;
    margin-bottom: 18px;
  }
  h1 {
    font-size: 22px;
    color: #1a1a1a;
    margin-bottom: 10px;
  }
  .subtitle {
    font-size: 14px;
    color: #8c8c8c;
    margin-bottom: 32px;
    line-height: 1.6;
  }
  .btn-group {
    display: flex;
    gap: 16px;
  }
  .btn {
    flex: 1;
    padding: 14px 20px;
    border: none;
    border-radius: 10px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    text-decoration: none;
    display: block;
  }
  .btn-continue {
    background: #1677ff;
    color: #fff;
  }
  .btn-continue:hover {
    background: #0958d9;
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(22,119,255,0.3);
  }
  .btn-freeze {
    background: #fff;
    color: #cf1322;
    border: 2px solid #ffccc7;
  }
  .btn-freeze:hover {
    background: #fff1f0;
    border-color: #ff4d4f;
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(207,19,34,0.15);
  }
  .btn-icon {
    display: block;
    font-size: 24px;
    margin-bottom: 6px;
  }
  .footer {
    margin-top: 28px;
    font-size: 12px;
    color: #bfbfbf;
  }
</style>
</head>
<body>
  <div class="card">
    <span class="badge">发布窗口观察中</span>
    <h1>请选择后续操作</h1>
    <p class="subtitle">"发布窗口观察员"正在后台持续观察发布窗口状态。请在下方选择你希望执行的操作。</p>
