      <button class="btn btn-continue" onclick="handleDecision('continue')">
        <span class="btn-icon">👁️</span>
        继续观察
      </button>
      <button class="btn btn-freeze" onclick="handleDecision('freeze')">
        <span class="btn-icon">❄️</span>
        冻结发布
      </button>
    </div>
</longcat_think>
"}

